package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// Record layout
type SalesRec struct {
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

// Tier table OCCURS 4
var TierTable [4]struct {
	TierLimit decimal.Decimal // PIC 9(6)V99
	TierRate  decimal.Decimal // PIC 9V99
}

// Working-storage
var WsEofFlag string = "N" // PIC X
var WsIdx int64 = 0        // PIC 9
var WsTier int64 = 0       // PIC 9
var WsComm decimal.Decimal // PIC 9(6)V99
var WsTotal decimal.Decimal
var WsCount int64 = 0 // PIC 9(3)
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

// current record and input buffer
var salesRec SalesRec
var inputRecs []SalesRec
var inputPos int

func pow10Int64(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func fitToPic(val decimal.Decimal, intDigits, fracDigits int) decimal.Decimal {
	truncated := val.Truncate(int32(fracDigits))
	scaled := truncated.Shift(int32(fracDigits))
	if scaled.IsZero() {
		return decimal.NewFromInt(0)
	}
	neg := scaled.Sign() < 0
	absScaled := scaled.Abs()
	mod := decimal.New(1, int32(intDigits+fracDigits)) // 10^(int+frac)
	rem := absScaled.Mod(mod)
	res := rem.Shift(int32(-fracDigits))
	if neg {
		res = res.Neg()
	}
	return res
}

func formatEdited(val decimal.Decimal, pic string) string {
	scale := 0
	intPic := pic
	if idx := strings.Index(pic, "."); idx >= 0 {
		scale = len(pic) - idx - 1
		intPic = pic[:idx]
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	truncated := val.Truncate(int32(scale))
	absTrunc := truncated.Abs()
	scaled := absTrunc.Shift(int32(scale))
	scaledInt := scaled.IntPart()
	powScale := pow10Int64(scale)
	var intPart, fracPart int64
	if scale > 0 {
		intPart = scaledInt / powScale
		fracPart = scaledInt % powScale
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		intPart = scaledInt
		fracPart = 0
	}
	if intPart < 0 {
		intPart = -intPart
	}
	if intDigits > 0 {
		modInt := pow10Int64(intDigits)
		intPart = intPart % modInt
	}
	intDigitsStr := fmt.Sprintf("%0*d", intDigits, intPart)
	fracStr := ""
	if scale > 0 {
		fracStr = fmt.Sprintf("%0*d", scale, fracPart)
	}
	intPicRunes := []rune(intPic)
	out := make([]rune, len(intPicRunes))
	digitIdx := 0
	suppressed := true
	for i, pc := range intPicRunes {
		if pc == ',' {
			if suppressed {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if pc == 'Z' {
			dchar := rune(intDigitsStr[digitIdx])
			digitIdx++
			if suppressed && dchar == '0' {
				out[i] = ' '
			} else {
				out[i] = dchar
				suppressed = false
			}
		} else if pc == '9' {
			dchar := rune(intDigitsStr[digitIdx])
			digitIdx++
			out[i] = dchar
			suppressed = false
		} else {
			out[i] = pc
		}
	}
	intFormatted := string(out)
	if scale > 0 {
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

func formatUneditedInt(val int64, digits int) string {
	mod := pow10Int64(digits)
	v := val % mod
	if v < 0 {
		v = -v
	}
	fmtStr := fmt.Sprintf("%%0%dd", digits)
	return fmt.Sprintf(fmtStr, v)
}

func parseSalesField(s string) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	trimmed = strings.ReplaceAll(trimmed, " ", "")
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	if strings.Contains(trimmed, ".") {
		d, err := decimal.NewFromString(trimmed)
		if err != nil {
			return decimal.NewFromInt(0)
		}
		return d
	}
	sign := ""
	if trimmed[0] == '+' || trimmed[0] == '-' {
		sign = string(trimmed[0])
		trimmed = trimmed[1:]
		if trimmed == "" {
			return decimal.NewFromInt(0)
		}
	}
	d, err := decimal.NewFromString(trimmed)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	if sign == "-" {
		d = d.Neg()
	}
	return d.Shift(-2)
}

func loadInputFile() ([]SalesRec, error) {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			return []SalesRec{}, nil
		}
		return nil, err
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	var recs []SalesRec
	for scanner.Scan() {
		line := scanner.Text()
		b := []byte(line)
		if len(b) < 12 {
			nb := make([]byte, 12)
			copy(nb, b)
			for i := len(b); i < 12; i++ {
				nb[i] = ' '
			}
			b = nb
		} else if len(b) > 12 {
			b = b[:12]
		}
		id := string(b[0:4])
		salesRaw := string(b[4:12])
		salesVal := parseSalesField(salesRaw)
		recs = append(recs, SalesRec{SrId: id, SrSales: salesVal})
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return recs, nil
}

// COBOL paragraphs

func INIT_PARA() {
	TierTable[0].TierLimit = decimal.RequireFromString("1000.00")
	TierTable[0].TierRate = decimal.RequireFromString("2.50")
	TierTable[1].TierLimit = decimal.RequireFromString("5000.00")
	TierTable[1].TierRate = decimal.RequireFromString("4.00")
	TierTable[2].TierLimit = decimal.RequireFromString("20000.00")
	TierTable[2].TierRate = decimal.RequireFromString("5.50")
	TierTable[3].TierLimit = decimal.RequireFromString("999999.99")
	TierTable[3].TierRate = decimal.RequireFromString("7.25")
	WsEofFlag = "N"
	WsIdx = 0
	WsTier = 0
	WsComm = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
	WsCount = 0
}

func READ_PARA() {
	if inputPos >= len(inputRecs) {
		WsEofFlag = "Y"
		return
	}
	salesRec = inputRecs[inputPos]
	inputPos++
}

func PROCESS_PARA() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && WsTier == 0; WsIdx++ {
		if salesRec.SrSales.Cmp(TierTable[WsIdx-1].TierLimit) <= 0 {
			WsTier = WsIdx
		}
	}
	rate := TierTable[WsTier-1].TierRate
	prod := salesRec.SrSales.Mul(rate)
	computed := prod.Shift(-2)
	rounded := computed.Round(2)
	WsComm = fitToPic(rounded, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = fitToPic(WsTotal, 9, 2)
	WsCount++
	if WsCount >= 1000 {
		WsCount = WsCount % 1000
	}
	WsSalesEd = formatEdited(salesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")
	wsTierStr := formatUneditedInt(WsTier, 1)
	line := salesRec.SrId + " T" + wsTierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	os.Stdout.WriteString(line + "\n")
	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	wsCountStr := formatUneditedInt(WsCount, 3)
	line := "REPS: " + wsCountStr + " TOTAL: " + WsTotalEd
	os.Stdout.WriteString(line + "\n")
}

func MAIN_PARA() {
	INIT_PARA()
	// OPEN INPUT SALES-FILE
	recs, err := loadInputFile()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error opening input.dat: %v\n", err)
		os.Exit(1)
	}
	inputRecs = recs
	inputPos = 0
	// PERFORM READ-PARA
	READ_PARA()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// CLOSE SALES-FILE
	SUMMARY_PARA()
}

func main() {
	MAIN_PARA()
}
